//! AWS managed policies.
//!
//! Every AWS managed policy (name, path, id, dates and the default
//! version's document) is vendored in `data/aws-managed-policies.jsonl`,
//! generated by `scripts/update-managed-policies.py` from the MAMIP
//! snapshots of `ListPolicies --scope AWS` and `GetPolicyVersion`.
//!
//! As in AWS they live in the `aws` namespace, not in any account: one
//! read-only [`Catalog`] per partition, built on first use, that every
//! account's [`Policies`] falls back to. Accounts only record which of them
//! their users, groups and roles attach.

use std::collections::{BTreeMap, HashMap};
use std::sync::{LazyLock, Mutex, OnceLock};

use chrono::{DateTime, Utc};
use mws_iam_policy::{Policy, PolicyKind};
use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::state::{ManagedPolicy, PolicyVersion};

const DATA: &str = include_str!("../data/aws-managed-policies.jsonl");

#[derive(Deserialize)]
struct Entry {
    name: String,
    path: String,
    id: String,
    version: String,
    created: DateTime<Utc>,
    updated: DateTime<Utc>,
    attachable: bool,
    #[serde(default)]
    description: Option<String>,
    document: String,
}

/// The AWS managed policies of one partition.
pub struct Catalog {
    policies: Vec<ManagedPolicy>,
    by_arn: HashMap<String, usize>,
    by_name: HashMap<String, usize>,
    /// Parsed default documents, filled in on first use.
    parsed: Vec<OnceLock<Option<Policy>>>,
}

impl Catalog {
    fn build(partition: &str) -> Self {
        let mut policies = Vec::new();
        for line in DATA.lines().filter(|l| !l.is_empty()) {
            let e: Entry = serde_json::from_str(line).expect("vendored AWS managed policy is valid");
            let arn = format!("arn:{partition}:iam::aws:policy{}{}", e.path, e.name);
            policies.push(ManagedPolicy {
                name: e.name,
                path: e.path,
                id: e.id,
                arn,
                created: e.created,
                updated: e.updated,
                description: e.description,
                versions: vec![PolicyVersion { id: e.version.clone(), document: e.document, created: e.updated }],
                default_version: e.version,
                next_version: 0,
                tags: vec![],
                aws_managed: true,
                attachable: e.attachable,
            });
        }
        let by_arn = policies.iter().enumerate().map(|(i, p)| (p.arn.clone(), i)).collect();
        let by_name = policies.iter().enumerate().map(|(i, p)| (p.name.clone(), i)).collect();
        let parsed = policies.iter().map(|_| OnceLock::new()).collect();
        Self { policies, by_arn, by_name, parsed }
    }

    pub fn get(&self, arn: &str) -> Option<&ManagedPolicy> {
        self.by_arn.get(arn).map(|&i| &self.policies[i])
    }

    /// The policy called `name`, whatever its path.
    pub fn by_name(&self, name: &str) -> Option<&ManagedPolicy> {
        self.by_name.get(name).map(|&i| &self.policies[i])
    }

    /// The parsed default document of `arn`, parsed once per process.
    pub fn parsed(&self, arn: &str) -> Option<&Policy> {
        let &i = self.by_arn.get(arn)?;
        self.parsed[i]
            .get_or_init(|| Policy::parse(self.policies[i].default_document(), PolicyKind::Identity).ok())
            .as_ref()
    }

    pub fn iter(&self) -> impl Iterator<Item = &ManagedPolicy> + Clone {
        self.policies.iter()
    }

    pub fn len(&self) -> usize {
        self.policies.len()
    }
}

/// The catalog for `partition` (`aws` when empty).
pub fn catalog(partition: &str) -> &'static Catalog {
    static CATALOGS: LazyLock<Mutex<HashMap<String, &'static Catalog>>> = LazyLock::new(Default::default);
    let partition = if partition.is_empty() { "aws" } else { partition };
    let mut map = CATALOGS.lock().expect("managed policy catalog lock poisoned");
    map.entry(partition.to_string()).or_insert_with(|| Box::leak(Box::new(Catalog::build(partition))))
}

/// The managed policies an account sees: its own customer managed policies
/// plus the AWS managed ones of its partition. Only the customer managed
/// ones are stored (and saved).
#[derive(Debug, Clone, Default)]
pub struct Policies {
    local: BTreeMap<String, ManagedPolicy>,
    partition: String,
}

impl Policies {
    /// Which partition's AWS managed policies this account sees.
    pub fn set_partition(&mut self, partition: &str) {
        self.partition = partition.to_string();
    }

    pub fn aws(&self) -> &'static Catalog {
        catalog(&self.partition)
    }

    /// A customer managed policy, or an AWS managed one.
    pub fn get(&self, arn: &str) -> Option<&ManagedPolicy> {
        self.local.get(arn).or_else(|| self.aws().get(arn))
    }

    pub fn contains_key(&self, arn: &str) -> bool {
        self.get(arn).is_some()
    }

    pub fn is_aws_managed(&self, arn: &str) -> bool {
        self.aws().get(arn).is_some()
    }

    /// A customer managed policy, for changes (AWS managed ones are
    /// read-only).
    pub fn get_mut(&mut self, arn: &str) -> Option<&mut ManagedPolicy> {
        self.local.get_mut(arn)
    }

    pub fn insert(&mut self, arn: String, p: ManagedPolicy) {
        self.local.insert(arn, p);
    }

    pub fn remove(&mut self, arn: &str) -> Option<ManagedPolicy> {
        self.local.remove(arn)
    }

    /// Customer managed policies, by ARN.
    pub fn local(&self) -> impl Iterator<Item = &ManagedPolicy> + Clone {
        self.local.values()
    }

    /// Every policy: customer managed ones first, then AWS managed ones.
    pub fn values(&self) -> impl Iterator<Item = &ManagedPolicy> + Clone {
        self.local.values().chain(self.aws().iter())
    }

    /// The parsed default document of an AWS managed policy (parsed once).
    pub fn parsed_aws(&self, arn: &str) -> Option<&'static Policy> {
        self.aws().parsed(arn)
    }
}

impl Serialize for Policies {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        self.local.serialize(s)
    }
}

impl<'de> Deserialize<'de> for Policies {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        // State saved by older versions also holds the AWS managed policies
        // MWS knew then; they now come from the catalog.
        let mut local = BTreeMap::<String, ManagedPolicy>::deserialize(d)?;
        local.retain(|_, p| !p.aws_managed);
        Ok(Self { local, partition: String::new() })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_document_parses() {
        let c = catalog("aws");
        assert!(c.len() > 1300, "only {} AWS managed policies", c.len());
        let mut bad = vec![];
        for p in c.iter() {
            if let Err(e) = Policy::parse(p.default_document(), PolicyKind::Identity) {
                bad.push(format!("{}: {e}", p.name));
            }
        }
        assert!(bad.is_empty(), "{} documents rejected:\n{}", bad.len(), bad.join("\n"));
    }

    #[test]
    fn known_policies() {
        let c = catalog("aws");
        let p = c.get("arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole").unwrap();
        assert_eq!(p.id, "ANPAJNCQGXC42545SKXIK");
        assert!(p.default_document().contains("logs:PutLogEvents"));
        assert_eq!(c.by_name("AWSSSOServiceRolePolicy").unwrap().path, "/aws-service-role/");
        assert!(c.get("arn:aws:iam::aws:policy/ReadOnlyAccess").unwrap().default_document().contains("s3:List"));
        let cn = catalog("aws-cn");
        assert!(cn.get("arn:aws-cn:iam::aws:policy/ReadOnlyAccess").is_some());
        assert!(cn.get("arn:aws:iam::aws:policy/ReadOnlyAccess").is_none());
    }

    #[test]
    fn saved_aws_policies_are_dropped() {
        let p = ManagedPolicy {
            name: "ReadOnlyAccess".into(),
            path: "/".into(),
            id: "ANPAX".into(),
            arn: "arn:aws:iam::aws:policy/ReadOnlyAccess".into(),
            created: Utc::now(),
            updated: Utc::now(),
            description: None,
            default_version: "v1".into(),
            versions: vec![],
            next_version: 2,
            tags: vec![],
            aws_managed: true,
            attachable: true,
        };
        let json = serde_json::json!({ p.arn.clone(): p });
        let policies: Policies = serde_json::from_value(json).unwrap();
        assert_eq!(policies.local().count(), 0);
        assert_eq!(policies.get("arn:aws:iam::aws:policy/ReadOnlyAccess").unwrap().id, "ANPAILL3HVNFSB6DCOWYQ");
    }
}
